import React, { useState, useEffect, useCallback } from 'react';
import ReactFlow, {
  MiniMap,
  Controls,
  Background,
  addEdge,
  useNodesState,
  useEdgesState,
} from 'reactflow';
import 'reactflow/dist/style.css';

function buildFolderNodesEdges(folderNode, parentId = null, posX = 0, posY = 0) {
  const nodes = [];
  const edges = [];
  if (!folderNode || !folderNode.children) return { nodes, edges };

  folderNode.children.forEach((child, idx) => {
    const id = parentId ? `${parentId}/${child.name}` : child.name;

    nodes.push({
      id,
      data: { label: child.name, nodeData: child },
      position: { x: posX + 200, y: posY + idx * 100 },
      style: {
        border: '1px solid black',
        borderRadius: 6,
        padding: 10,
        cursor: 'pointer',
        backgroundColor:
          child.children && child.children.length ? '#90caf9' : '#ffd54f',
        fontWeight: '600',
        minWidth: 140,
        textAlign: 'center',
      },
    });

    if (parentId) {
      edges.push({
        id: `containment-${parentId}->${id}`,
        source: parentId,
        target: id,
        animated: true,
        style: { stroke: '#888' },
      });
    }
  });

  if (parentId) {
    nodes.push({
      id: parentId,
      data: { label: folderNode.name, nodeData: folderNode },
      position: {
        x: posX,
        y: posY + ((folderNode.children.length - 1) * 100) / 2,
      },
      style: {
        border: '2px solid #333',
        borderRadius: 8,
        padding: 12,
        fontWeight: 'bold',
        backgroundColor: '#66bb6a',
        minWidth: 160,
        textAlign: 'center',
        cursor: 'pointer',
      },
    });
  }

  return { nodes, edges };
}

function findNodeById(currentNode, id, path = '') {
  if (!currentNode) return null;
  const currentId = path ? `${path}/${currentNode.name}` : currentNode.name;
  if (currentId === id) return currentNode;
  if (!currentNode.children) return null;
  for (const child of currentNode.children) {
    const found = findNodeById(child, id, currentId);
    if (found) return found;
  }
  return null;
}

export default function App() {
  const [treeData, setTreeData] = useState(null);
  const [currentFolder, setCurrentFolder] = useState(null);
  const [nodes, setNodes, onNodesChange] = useNodesState([]);
  const [edges, setEdges, onEdgesChange] = useEdgesState([]);

  // For demo, static import edges to show file usage relationships (replace with backend data)
  const importEdges = [
    // { id: 'import1', source: 'src/components/App.js', target: 'src/index.js', animated: true, style: { stroke: 'red' } },
  ];

  const uploadZip = async (e) => {
    const file = e.target.files[0];
    if (!file) return;
    const formData = new FormData();
    formData.append('repoZip', file);
    try {
      const res = await fetch('http://localhost:5000/upload', {
        method: 'POST',
        body: formData,
      });
      if (res.ok) {
        const data = await res.json();
        setTreeData(data);
        setCurrentFolder(data);
      } else {
        alert('Upload failed');
      }
    } catch {
      alert('Error uploading file');
    }
  };

  useEffect(() => {
    if (!currentFolder) {
      setNodes([]);
      setEdges([]);
      return;
    }
    const parentId = currentFolder.name === 'root' ? null : currentFolder.name;
    const { nodes: folderNodes, edges: folderEdges } = buildFolderNodesEdges(
      currentFolder,
      parentId
    );
    // Combine edges: folder containment + import relations
    setNodes(folderNodes);
    setEdges([...folderEdges, ...importEdges]);
  }, [currentFolder, setNodes, setEdges]);

  // Handle node click with double click detection
  const onNodeClick = useCallback(
    (event, node) => {
      if (event.detail === 2) {
        // Double click: drill down if folder
        if (node.data.nodeData.children && node.data.nodeData.children.length > 0) {
          const folderNode = findNodeById(treeData, node.id);
          if (folderNode) {
            setCurrentFolder(folderNode);
          }
        }
      }
    },
    [treeData]
  );

  const goBack = () => {
    if (!currentFolder || currentFolder.name === 'root') return;
    const pathParts = currentFolder.name.split('/');
    if (pathParts.length === 1) {
      setCurrentFolder(treeData); // back to root
    } else {
      pathParts.pop();
      const parentPath = pathParts.join('/');
      const parentNode = findNodeById(treeData, parentPath);
      if (parentNode) setCurrentFolder(parentNode);
    }
  };

  return (
    <div style={{ height: '100vh', width: '100vw', padding: 20, boxSizing: 'border-box' }}>
      <h1>Repository Visualizer With Real Relations</h1>
      <input type="file" accept=".zip" onChange={uploadZip} />
      {currentFolder && currentFolder.name !== 'root' && (
        <button onClick={goBack} style={{ marginTop: 10, marginBottom: 10 }}>
          &larr; Back to Parent Folder
        </button>
      )}
      <div style={{ height: '80%', border: '1px solid #ccc' }}>
        <ReactFlow
          nodes={nodes}
          edges={edges}
          onNodesChange={onNodesChange}
          onEdgesChange={onEdgesChange}
          onNodeClick={onNodeClick}
          fitView
        >
          <MiniMap />
          <Controls />
          <Background />
        </ReactFlow>
      </div>
    </div>
  );
}
